mapper.insert:

    /*  isry.couns.taskwksprt.fbdnwdreg.mapper.FbdnwdRegMapper.insertFbdnwdReg : 금칙어 등록 */
    INSERT  INTO    AYC490
    (
        INDEX_SN        /* 게시판 번호 */
    ,   PRWO_NM         /*  금칙어명 */
    ,   FRST_RGTR_ID    /* 최초등록자 아이디 */
    ,   FRST_REG_DT     /*  최초등록일시 */
    ,   DEL_YN
    )
    VALUES
    (
		(
		SELECT NVL(MAX(INDEX_SN), 0) +1 AS INDEX_SN
		   FROM AYC490
		)
    ,   #{PRWO_NM}
    ,   #{loginId}
    ,   SYSDATE
    ,   'N'
    )

mapper.update:
/*  isry.couns.taskwksprt.fbdnwdreg.mapper.FbdnwdRegMapper.deleteFbdnwdReg : 금칙어 삭제 */ 
UPDATE 
        AYC490 
SET
        DEL_YN          =	'Y'
    ,   LAST_MDFR_ID	=	#{loginId}
    ,   LAST_MDFCN_DT	=	SYSDATE
WHERE   INDEX_SN        =   #{INDEX_SN}

/*  isry.couns.taskwksprt.fbdnwdreg.mapper.FbdnwdRegMapper.updateFbdnwdReg : 금칙어 수정 */ 
UPDATE 
        AYC490 
SET
        PRWO_NM         =   #{PRWO_NM}
    ,   LAST_MDFR_ID	=	#{loginId}
    ,   LAST_MDFCN_DT	=	SYSDATE
WHERE   INDEX_SN        =   #{INDEX_SN}
